CREATE TABLE IF NOT EXISTS installment_contracts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE RESTRICT, party_id uuid NOT NULL REFERENCES parties(id) ON DELETE RESTRICT, item_id uuid REFERENCES items(id) ON DELETE SET NULL, source_invoice_id uuid REFERENCES sales_invoices(id) ON DELETE SET NULL, number text, contract_value numeric(20,4) NOT NULL, down_payment numeric(20,4) NOT NULL DEFAULT 0, installment_count int NOT NULL CHECK (installment_count > 0), period_unit text NOT NULL DEFAULT 'months' CHECK (period_unit IN ('days','months')), period_every int NOT NULL DEFAULT 1 CHECK (period_every > 0), first_due_date date NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','closed','voided')), early_settlement_discount numeric(20,4) NOT NULL DEFAULT 0, summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS installment_contracts_number_key ON installment_contracts(tenant_id, number) WHERE number IS NOT NULL;
CREATE INDEX IF NOT EXISTS installment_contracts_party_idx ON installment_contracts(tenant_id, party_id, status);
CREATE TABLE IF NOT EXISTS installment_schedule (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, contract_id uuid NOT NULL REFERENCES installment_contracts(id) ON DELETE CASCADE, line_no int NOT NULL, due_date date NOT NULL, due_value numeric(20,4) NOT NULL, paid_value numeric(20,4) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','partial','paid','overdue','waived')), voucher_id uuid REFERENCES vouchers(id) ON DELETE SET NULL, collected_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS installment_schedule_line_key ON installment_schedule(contract_id, line_no);
CREATE INDEX IF NOT EXISTS installment_schedule_due_idx ON installment_schedule(tenant_id, due_date, status);
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid REFERENCES branches(id) ON DELETE RESTRICT, code text NOT NULL, name text NOT NULL, party_id uuid NOT NULL REFERENCES parties(id) ON DELETE RESTRICT, contractor_party_id uuid REFERENCES parties(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','on_hold','closed','voided')), starts_on date, ends_on date, contract_value numeric(20,4) NOT NULL DEFAULT 0, retention_pct numeric(7,4) NOT NULL DEFAULT 0, cost_center_id uuid REFERENCES cost_centers(id) ON DELETE SET NULL, summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS projects_code_key ON projects(tenant_id, code) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS projects_party_idx ON projects(tenant_id, party_id, status);
CREATE TABLE IF NOT EXISTS project_stage_templates (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, stages jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS project_stage_templates_name_key ON project_stage_templates(tenant_id, name) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS project_stages (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name text NOT NULL, stage_order int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','accredited','rejected')), accredited_by uuid REFERENCES users(id) ON DELETE SET NULL, accredited_at timestamptz, accreditation_note text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS project_stages_order_key ON project_stages(project_id, stage_order);
CREATE INDEX IF NOT EXISTS project_stages_project_idx ON project_stages(tenant_id, project_id, status);
CREATE TABLE IF NOT EXISTS boq_terms (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, code text NOT NULL, description text NOT NULL, qty numeric(20,4) NOT NULL DEFAULT 1, unit_value numeric(20,4) NOT NULL, estimated_cost numeric(20,4) NOT NULL DEFAULT 0, execution_period text, previously_billed numeric(20,4) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS boq_terms_code_key ON boq_terms(tenant_id, project_id, code) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS boq_terms_project_idx ON boq_terms(tenant_id, project_id);
CREATE TABLE IF NOT EXISTS progress_bills (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT, number text, bill_date date NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','posted','released','voided')), work_value numeric(20,4) NOT NULL DEFAULT 0, previous_value numeric(20,4) NOT NULL DEFAULT 0, retention_value numeric(20,4) NOT NULL DEFAULT 0, net_due numeric(20,4) NOT NULL DEFAULT 0, invoice_id uuid REFERENCES sales_invoices(id) ON DELETE SET NULL, posted_at timestamptz, released_at timestamptz, summary jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS progress_bills_number_key ON progress_bills(tenant_id, number) WHERE number IS NOT NULL;
CREATE INDEX IF NOT EXISTS progress_bills_project_idx ON progress_bills(tenant_id, project_id, status);
CREATE TABLE IF NOT EXISTS progress_bill_lines (bill_id uuid NOT NULL REFERENCES progress_bills(id) ON DELETE CASCADE, line_no int NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, term_id uuid NOT NULL REFERENCES boq_terms(id) ON DELETE RESTRICT, bill_pct numeric(7,4) NOT NULL DEFAULT 0, bill_value numeric(20,4) NOT NULL, previous_value numeric(20,4) NOT NULL DEFAULT 0, remaining_value numeric(20,4) NOT NULL DEFAULT 0, PRIMARY KEY(bill_id, line_no));
CREATE INDEX IF NOT EXISTS progress_bill_lines_term_idx ON progress_bill_lines(tenant_id, term_id);
CREATE TABLE IF NOT EXISTS project_requirements (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE CASCADE, party_id uuid REFERENCES parties(id) ON DELETE SET NULL, title text NOT NULL, status text NOT NULL DEFAULT 'open', payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS project_requirements_status_idx ON project_requirements(tenant_id, status);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['installment_contracts','installment_schedule','projects','project_stage_templates','project_stages','boq_terms','progress_bills','progress_bill_lines','project_requirements'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('DROP POLICY IF EXISTS %I_tenant_isolation ON %I', t, t); EXECUTE format('CREATE POLICY %I_tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', t, t); END LOOP; END $$;
